def load_family_agent_eval_scenarios(
    *, scenarios_path: Path | None = None
) -> list[FamilyAgentEvalScenario]:
    path = scenarios_path or Path(__file__).with_name("scenarios.json")
    raw_payload = json.loads(path.read_text())
    if not isinstance(raw_payload, list):
        raise ValueError("Family-agent eval scenarios must be a JSON array")

    scenarios = [_parse_scenario(dict(item)) for item in raw_payload]
    scenario_ids = {scenario.id for scenario in scenarios}
    missing_ids = REQUIRED_SCENARIO_IDS - scenario_ids
    extra_ids = scenario_ids - REQUIRED_SCENARIO_IDS
    if missing_ids or extra_ids:
        raise ValueError(
            "Family-agent eval scenario ids do not match the required catalog: "
            f"missing={sorted(missing_ids)} extra={sorted(extra_ids)}"
        )
    if len(scenario_ids) != len(scenarios):
        raise ValueError("Family-agent eval scenario ids must be unique")
    return scenarios


def filter_family_agent_eval_scenarios(
    scenarios: list[FamilyAgentEvalScenario], *, suite: EvalSuite
) -> list[FamilyAgentEvalScenario]:
    if suite == "smoke":
        return [scenario for scenario in scenarios if scenario.suite == "smoke"]
    return scenarios

