class FamilyAgentEvalRunner:
    def __init__(
        self,
        *,
        user: User,
        family: FamilyGroup,
        config: FamilyAgentEvalRunConfig,
    ) -> None:
        self.user = user
        self.family = family
        self.config = config

    def run(self) -> list[FamilyAgentEvalResult]:
        scenarios = filter_family_agent_eval_scenarios(
            load_family_agent_eval_scenarios(),
            suite=self.config.suite,
        )
        results: list[FamilyAgentEvalResult] = []
        for model_name in self.config.models:
            for scenario in scenarios:
                for run_index in range(1, self.config.runs + 1):
                    results.append(
                        self.run_scenario(
                            scenario,
                            model_name=model_name,
                            run_index=run_index,
                        )
                    )
        return results

    def run_scenario(
        self,
        scenario: FamilyAgentEvalScenario,
        *,
        model_name: str,
        run_index: int,
    ) -> FamilyAgentEvalResult:
        started_at = timezone.now().isoformat()
        started_monotonic = time.monotonic()
        try:
            with override_settings(FAMILY_AGENT_HERMES_MODEL=model_name):
                classifier_client = (
                    _FakeScopeClassifierClient(scenario.fake_scope_classifier_output)
                    if not self.config.live
                    and scenario.fake_scope_classifier_output is not None
                    else None
                )
                runtime = HermesFamilyPlannerRuntime(
                    external_research_enabled=(
                        self.config.live and self.config.allow_external_research
                    ),
                    scope_classifier_client=classifier_client,
                )
                if not self.config.live:
                    self._install_offline_replay(runtime=runtime, scenario=scenario)
                response = runtime.execute(
                    user=self.user,
                    family=self.family,
                    message_text=scenario.message_text,
                    context_payload=scenario.context_payload,
                    run_id=f"eval:{scenario.id}:{model_name}:{run_index}",
                )
            normalized_response = self._normalize_response(response)
            gate_results = evaluate_family_agent_eval_result(
                scenario=scenario,
                response=normalized_response,
            )
            latency_ms = int((time.monotonic() - started_monotonic) * 1000)
            return FamilyAgentEvalResult(
                scenario_id=scenario.id,
                model_name=model_name,
                run_index=run_index,
                passed=all(gate.passed for gate in gate_results),
                gate_results=gate_results,
                normalized_response=normalized_response,
                tool_calls=self._tool_calls(normalized_response),
                latency_ms=latency_ms,
                started_at=started_at,
            )
        except Exception as exc:
            latency_ms = int((time.monotonic() - started_monotonic) * 1000)
            return self.build_error_result(
                scenario=scenario,
                model_name=model_name,
                run_index=run_index,
                error=exc,
                started_at_iso=started_at,
                latency_ms=latency_ms,
            )

    @staticmethod
    def build_error_result(
        *,
        scenario: FamilyAgentEvalScenario,
        model_name: str,
        run_index: int,
        error: Exception,
        started_at_iso: str,
        latency_ms: int,
    ) -> FamilyAgentEvalResult:
        return FamilyAgentEvalResult(
            scenario_id=scenario.id,
            model_name=model_name,
            run_index=run_index,
            passed=False,
            gate_results=[
                FamilyAgentEvalGateResult(
                    name="runtime_error",
                    passed=False,
                    message=str(error),
                )
            ],
            normalized_response={},
            tool_calls=[],
            latency_ms=latency_ms,
            started_at=started_at_iso,
            error=str(error),
        )

    def _install_offline_replay(
        self,
        *,
        runtime: HermesFamilyPlannerRuntime,
        scenario: FamilyAgentEvalScenario,
    ) -> None:
        fake_agent = _FakeScenarioAgent(scenario.fake_model_outputs)
        runtime._build_agent = lambda: fake_agent  # type: ignore[method-assign]

        for tool_name, results in scenario.fake_tool_results.items():

            def fake_tool_method_factory(
                queued_results: list[Any],
            ) -> Any:
                def fake_tool_method(**kwargs: Any) -> Any:
                    del kwargs
                    if queued_results:
                        return queued_results.pop(0)
                    return {}

                return fake_tool_method

            setattr(
                runtime.tool_adapter,
                tool_name,
                fake_tool_method_factory(list(results)),
            )

    def _normalize_response(self, response: dict[str, Any]) -> dict[str, Any]:
        normalized = dict(response)
        usage_json = dict(normalized.get("usage_json") or {})
        usage_json.setdefault("availability_tool_calls", [])
        usage_json.setdefault("model_call_count", 0)
        usage_json.setdefault("estimated_input_tokens", 0)
        usage_json.setdefault("estimated_output_tokens", 0)
        usage_json.setdefault("estimated_total_cost_micros", 0)
        normalized["usage_json"] = usage_json
        return normalized

    def _tool_calls(self, response: dict[str, Any]) -> list[dict[str, Any]]:
        usage_json = response.get("usage_json")
        if not isinstance(usage_json, dict):
            return []
        calls = usage_json.get("availability_tool_calls")
        if not isinstance(calls, list):
            return []
        return [call for call in calls if isinstance(call, dict)]


def _summarize_results(results: list[FamilyAgentEvalResult]) -> dict[str, int]:
    passed = sum(1 for result in results if result.passed)
    total = len(results)
    return {
        "total": total,
        "passed": passed,
        "failed": total - passed,
    }


def _build_markdown_report(
    *,
    results: list[FamilyAgentEvalResult],
    config: FamilyAgentEvalRunConfig,
) -> str:
    summary = _summarize_results(results)
    lines = [
        "# Family Agent Eval Results",
        "",
        f"- Suite: `{config.suite}`",
        f"- Mode: `{'live' if config.live else 'offline'}`",
        f"- Models: `{', '.join(config.models)}`",
        f"- Runs per scenario: `{config.runs}`",
        f"- Passed: `{summary['passed']}/{summary['total']}`",
        "",
        "| Model | Scenario | Run | Result | Latency | Failed Gates |",
        "| --- | --- | ---: | --- | ---: | --- |",
    ]
    for result in results:
        failed_gates = ", ".join(
            gate.name for gate in result.gate_results if not gate.passed
        )
        lines.append(
            "| "
            f"{result.model_name} | "
            f"{result.scenario_id} | "
            f"{result.run_index} | "
            f"{'PASS' if result.passed else 'FAIL'} | "
            f"{result.latency_ms}ms | "
            f"{failed_gates or '-'} |"
        )
    lines.append("")
    return "\n".join(lines)


def write_family_agent_eval_artifacts(
    *,
    results: list[FamilyAgentEvalResult],
    output_path: Path,
    config: FamilyAgentEvalRunConfig,
) -> tuple[Path, Path]:
    output_path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "config": {
            "suite": config.suite,
            "models": config.models,
            "runs": config.runs,
            "live": config.live,
            "allow_external_research": config.allow_external_research,
        },
        "summary": _summarize_results(results),
        "results": [result.to_dict() for result in results],
    }
    output_path.write_text(json.dumps(payload, indent=2, sort_keys=True, default=str))
    markdown_path = output_path.with_suffix(".md")
    markdown_path.write_text(_build_markdown_report(results=results, config=config))
    return output_path, markdown_path
